import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-go-array-manipulation-in-go":{"intro":"This challenge will test your understanding of arrays in Golang. You will be required to create and manipulate arrays of different types.","steps":[{"title":"Arrays","body":["You are required to create an array of integers with a length of 5. You will then set a value at a specific index and retrieve a value from a specific index. You will also be required to find the length of the array and declare and initialize an array in one line. Finally, you will create a two-dimensional array and initialize it with values.","• Create an array of integers with a length of 5 • Set a value at a specific index and retrieve a value from a specific index • Find the length of the array • Declare and initialize an array in one line • Create a two-dimensional array and initialize it with values"],"code":[{"lang":"sh","text":"# Note that arrays appear in the form `[v1 v2 v3 ...]`\n# when printed with `fmt.Println`.\n$ go run arrays.go\nemp: [0 0 0 0 0]\nset: [0 0 0 0 100]\nget: 100\nlen: 5\ndcl: [1 2 3 4 5]\n2d: [[0 1 2] [1 2 3]]"}]}],"commands":["go run arrays.go"],"reference":[{"path":"arrays.go","text":"// In Go, an _array_ is a numbered sequence of elements of a\n// specific length. In typical Go code, [slices](slices) are\n// much more common; arrays are useful in some special\n// scenarios.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Here we create an array `a` that will hold exactly\n\t// 5 `int`s. The type of elements and length are both\n\t// part of the array's type. By default an array is\n\t// zero-valued, which for `int`s means `0`s.\n\tvar a [5]int\n\tfmt.Println(\"emp:\", a)\n\n\t// We can set a value at an index using the\n\t// `array[index] = value` syntax, and get a value with\n\t// `array[index]`.\n\ta[4] = 100\n\tfmt.Println(\"set:\", a)\n\tfmt.Println(\"get:\", a[4])\n\n\t// The builtin `len` returns the length of an array.\n\tfmt.Println(\"len:\", len(a))\n\n\t// Use this syntax to declare and initialize an array\n\t// in one line.\n\tb := [5]int{1, 2, 3, 4, 5}\n\tfmt.Println(\"dcl:\", b)\n\n\t// Array types are one-dimensional, but you can\n\t// compose types to build multi-dimensional data\n\t// structures.\n\tvar twoD [2][3]int\n\tfor i := 0; i < 2; i++ {\n\t\tfor j := 0; j < 3; j++ {\n\t\t\ttwoD[i][j] = i + j\n\t\t}\n\t}\n\tfmt.Println(\"2d: \", twoD)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-atomic-counters-in-concurrent-go-programming":{"intro":"This challenge focuses on managing state in Go using the sync/atomic package for atomic counters accessed by multiple goroutines.","steps":[{"title":"Atomic Counters","body":["The problem is to increment a counter exactly 1000 times using 50 goroutines and the sync/atomic package.","• Use the sync/atomic package to increment the counter. • Use a WaitGroup to wait for all goroutines to finish their work."],"code":[{"lang":"sh","text":"# We expect to get exactly 50,000 operations. Had we\n# used the non-atomic `ops++` to increment the counter,\n# we'd likely get a different number, changing between\n# runs, because the goroutines would interfere with\n# each other. Moreover, we'd get data race failures\n# when running with the `-race` flag.\n$ go run atomic-counters.go\nops: 50000\n\n# Next we'll look at mutexes, another tool for managing\n# state."}]}],"commands":["go run atomic-counters.go"],"reference":[{"path":"atomic-counters.go","text":"// The primary mechanism for managing state in Go is\n// communication over channels. We saw this for example\n// with [worker pools](worker-pools). There are a few other\n// options for managing state though. Here we'll\n// look at using the `sync/atomic` package for _atomic\n// counters_ accessed by multiple goroutines.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"sync\"\n\t\"sync/atomic\"\n)\n\nfunc main() {\n\n\t// We'll use an unsigned integer to represent our\n\t// (always-positive) counter.\n\tvar ops uint64\n\n\t// A WaitGroup will help us wait for all goroutines\n\t// to finish their work.\n\tvar wg sync.WaitGroup\n\n\t// We'll start 50 goroutines that each increment the\n\t// counter exactly 1000 times.\n\tfor i := 0; i < 50; i++ {\n\t\twg.Add(1)\n\n\t\tgo func() {\n\t\t\tfor c := 0; c < 1000; c++ {\n\t\t\t\t// To atomically increment the counter we\n\t\t\t\t// use `AddUint64`, giving it the memory\n\t\t\t\t// address of our `ops` counter with the\n\t\t\t\t// `&` syntax.\n\t\t\t\tatomic.AddUint64(&ops, 1)\n\t\t\t}\n\t\t\twg.Done()\n\t\t}()\n\t}\n\n\t// Wait until all the goroutines are done.\n\twg.Wait()\n\n\t// It's safe to access `ops` now because we know\n\t// no other goroutine is writing to it. Reading\n\t// atomics safely while they are being updated is\n\t// also possible, using functions like\n\t// `atomic.LoadUint64`.\n\tfmt.Println(\"ops:\", ops)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-base64-encoding-challenge-in-go":{"intro":"This challenge aims to test your knowledge of base64 encoding in Golang.","steps":[{"title":"Base64 Encoding","body":["You are required to write a Golang program that encodes and decodes a given string using both standard and URL-compatible base64 encoding.","• The program should import the encoding/base64 package with the b64 name instead of the default base64. • The program should encode the given string using both standard and URL-compatible base64 encoding. • The program should decode the encoded string using both standard and URL-compatible base64 decoding. • The program should print the encoded and decoded strings to the console."],"code":[{"lang":"sh","text":"# The string encodes to slightly different values with the\n# standard and URL base64 encoders (trailing `+` vs `-`)\n# but they both decode to the original string as desired."}]}],"commands":[],"reference":[{"path":"base64-encoding.go","text":"// Go provides built-in support for [base64\n// encoding/decoding](https://en.wikipedia.org/wiki/Base64).\n\npackage main\n\n// This syntax imports the `encoding/base64` package with\n// the `b64` name instead of the default `base64`. It'll\n// save us some space below.\nimport (\n\tb64 \"encoding/base64\"\n\t\"fmt\"\n)\n\nfunc main() {\n\n\t// Here's the `string` we'll encode/decode.\n\tdata := \"abc123!?$*&()'-=@~\"\n\n\t// Go supports both standard and URL-compatible\n\t// base64. Here's how to encode using the standard\n\t// encoder. The encoder requires a `[]byte` so we\n\t// convert our `string` to that type.\n\tsEnc := b64.StdEncoding.EncodeToString([]byte(data))\n\tfmt.Println(sEnc)\n\n\t// Decoding may return an error, which you can check\n\t// if you don't already know the input to be\n\t// well-formed.\n\tsDec, _ := b64.StdEncoding.DecodeString(sEnc)\n\tfmt.Println(string(sDec))\n\tfmt.Println()\n\n\t// This encodes/decodes using a URL-compatible base64\n\t// format.\n\tuEnc := b64.URLEncoding.EncodeToString([]byte(data))\n\tfmt.Println(uEnc)\n\tuDec, _ := b64.URLEncoding.DecodeString(uEnc)\n\tfmt.Println(string(uDec))\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-buffered-channels":{"intro":"This challenge aims to test your understanding of buffered channels in Golang.","steps":[{"title":"Channel Buffering","body":["By default, channels in Golang are unbuffered, meaning that they only accept sends if there is a corresponding receive ready to receive the sent value. However, buffered channels accept a limited number of values without a corresponding receiver for those values. In this challenge, you are required to create a buffered channel and send values into the channel without a corresponding concurrent receive.","• Basic knowledge of Golang channels • Understanding of buffered channels"],"code":[{"lang":"sh","text":"$ go run channel-buffering.go\nbuffered\nchannel"}]}],"commands":["go run channel-buffering.go"],"reference":[{"path":"channel-buffering.go","text":"// By default channels are _unbuffered_, meaning that they\n// will only accept sends (`chan <-`) if there is a\n// corresponding receive (`<- chan`) ready to receive the\n// sent value. _Buffered channels_ accept a limited\n// number of  values without a corresponding receiver for\n// those values.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Here we `make` a channel of strings buffering up to\n\t// 2 values.\n\tmessages := make(chan string, 2)\n\n\t// Because this channel is buffered, we can send these\n\t// values into the channel without a corresponding\n\t// concurrent receive.\n\tmessages <- \"buffered\"\n\tmessages <- \"channel\"\n\n\t// Later we can receive these two values as usual.\n\tfmt.Println(<-messages)\n\tfmt.Println(<-messages)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-channel-function-parameters":{"intro":"This challenge aims to test your understanding of using channels as function parameters in Golang.","steps":[{"title":"Channel Directions","body":["The problem to be solved in this challenge is to modify the given code to ensure that the channels used as function parameters are specified to only send or receive values.","• Basic knowledge of Golang • Understanding of channels and their usage in Golang"],"code":[{"lang":"sh","text":"$ go run channel-directions.go\npassed message"}]}],"commands":["go run channel-directions.go"],"reference":[{"path":"channel-directions.go","text":"// When using channels as function parameters, you can\n// specify if a channel is meant to only send or receive\n// values. This specificity increases the type-safety of\n// the program.\n\npackage main\n\nimport \"fmt\"\n\n// This `ping` function only accepts a channel for sending\n// values. It would be a compile-time error to try to\n// receive on this channel.\nfunc ping(pings chan<- string, msg string) {\n\tpings <- msg\n}\n\n// The `pong` function accepts one channel for receives\n// (`pings`) and a second for sends (`pongs`).\nfunc pong(pings <-chan string, pongs chan<- string) {\n\tmsg := <-pings\n\tpongs <- msg\n}\n\nfunc main() {\n\tpings := make(chan string, 1)\n\tpongs := make(chan string, 1)\n\tping(pings, \"passed message\")\n\tpong(pings, pongs)\n\tfmt.Println(<-pongs)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-synchronize-goroutines-with-channels":{"intro":"This challenge aims to test your knowledge of using channels to synchronize execution across goroutines.","steps":[{"title":"Channel Synchronization","body":["The problem to be solved in this challenge is to create a goroutine that performs some work and notifies another goroutine when it's done using a channel.","To complete this challenge, you will need to:","• Create a function named worker that takes a channel of type bool as a parameter. • Inside the worker function, perform some work and then send a value to the channel to notify that the work is done. • In the main function, create a channel of type bool with a buffer size of 1. • Start a goroutine that calls the worker function and passes the channel as a parameter. • Block the main function until a value is received from the channel."],"code":[{"lang":"sh","text":"$ go run channel-synchronization.go\nworking...done\n\n# If you removed the `<- done` line from this program, the\n# program would exit before the `worker` even\n# started."}]}],"commands":["go run channel-synchronization.go"],"reference":[{"path":"channel-synchronization.go","text":"// We can use channels to synchronize execution\n// across goroutines. Here's an example of using a\n// blocking receive to wait for a goroutine to finish.\n// When waiting for multiple goroutines to finish,\n// you may prefer to use a [WaitGroup](waitgroups).\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\n// This is the function we'll run in a goroutine. The\n// `done` channel will be used to notify another\n// goroutine that this function's work is done.\nfunc worker(done chan bool) {\n\tfmt.Print(\"working...\")\n\ttime.Sleep(time.Second)\n\tfmt.Println(\"done\")\n\n\t// Send a value to notify that we're done.\n\tdone <- true\n}\n\nfunc main() {\n\n\t// Start a worker goroutine, giving it the channel to\n\t// notify on.\n\tdone := make(chan bool, 1)\n\tgo worker(done)\n\n\t// Block until we receive a notification from the\n\t// worker on the channel.\n\t<-done\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-channels-concurrency":{"intro":"The Channels challenge is designed to test your understanding of channels in Golang. Channels are used to connect concurrent goroutines, allowing values to be sent and received between them.","steps":[{"title":"Channels","body":["In this challenge, you are required to create a new channel and send a value into it from a new goroutine. You will then receive the value from the channel and print it out.","• You must use the make(chan val-type) syntax to create a new channel. • The channel must be typed by the values it conveys. • You must use the channel <- syntax to send a value into the channel. • You must use the <-channel syntax to receive a value from the channel. • You must use a new goroutine to send the value into the channel."],"code":[{"lang":"sh","text":"# When we run the program the `\"ping\"` message is\n# successfully passed from one goroutine to another via\n# our channel.\n$ go run channels.go\nping\n\n# By default sends and receives block until both the\n# sender and receiver are ready. This property allowed\n# us to wait at the end of our program for the `\"ping\"`\n# message without having to use any other synchronization."}]}],"commands":["go run channels.go"],"reference":[{"path":"channels.go","text":"// _Channels_ are the pipes that connect concurrent\n// goroutines. You can send values into channels from one\n// goroutine and receive those values into another\n// goroutine.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Create a new channel with `make(chan val-type)`.\n\t// Channels are typed by the values they convey.\n\tmessages := make(chan string)\n\n\t// _Send_ a value into a channel using the `channel <-`\n\t// syntax. Here we send `\"ping\"`  to the `messages`\n\t// channel we made above, from a new goroutine.\n\tgo func() { messages <- \"ping\" }()\n\n\t// The `<-channel` syntax _receives_ a value from the\n\t// channel. Here we'll receive the `\"ping\"` message\n\t// we sent above and print it out.\n\tmsg := <-messages\n\tfmt.Println(msg)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-channel-communication-with-workers":{"intro":"In Golang, closing a channel can be used to communicate completion to the channel's receivers. This challenge will demonstrate how to use a channel to communicate work to be done from the main() goroutine to a worker goroutine, and how to close the channel when there are no more jobs for the worker.","steps":[{"title":"Closing Channels","body":["In this challenge, you need to modify the given code to close the jobs channel when there are no more jobs for the worker. You also need to use the done channel to notify when all the jobs have been completed.","• Use a buffered channel jobs to communicate work to be done from the main() goroutine to a worker goroutine. • Use a channel done to notify when all the jobs have been completed. • Use a worker goroutine to repeatedly receive from jobs with j, more := <-jobs. • Use the special 2-value form of receive to notify on done when all the jobs have been completed. • Send 3 jobs to the worker over the jobs channel, then close it. • Use the [synchronization](channel-synchronization) approach to await the worker."],"code":[{"lang":"sh","text":"$ go run closing-channels.go\nsent job 1\nreceived job 1\nsent job 2\nreceived job 2\nsent job 3\nreceived job 3\nsent all jobs\nreceived all jobs\n\n# The idea of closed channels leads naturally to our next\n# example: `range` over channels."}]}],"commands":["go run closing-channels.go"],"reference":[{"path":"closing-channels.go","text":"// _Closing_ a channel indicates that no more values\n// will be sent on it. This can be useful to communicate\n// completion to the channel's receivers.\n\npackage main\n\nimport \"fmt\"\n\n// In this example we'll use a `jobs` channel to\n// communicate work to be done from the `main()` goroutine\n// to a worker goroutine. When we have no more jobs for\n// the worker we'll `close` the `jobs` channel.\nfunc main() {\n\tjobs := make(chan int, 5)\n\tdone := make(chan bool)\n\n\t// Here's the worker goroutine. It repeatedly receives\n\t// from `jobs` with `j, more := <-jobs`. In this\n\t// special 2-value form of receive, the `more` value\n\t// will be `false` if `jobs` has been `close`d and all\n\t// values in the channel have already been received.\n\t// We use this to notify on `done` when we've worked\n\t// all our jobs.\n\tgo func() {\n\t\tfor {\n\t\t\tj, more := <-jobs\n\t\t\tif more {\n\t\t\t\tfmt.Println(\"received job\", j)\n\t\t\t} else {\n\t\t\t\tfmt.Println(\"received all jobs\")\n\t\t\t\tdone <- true\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}()\n\n\t// This sends 3 jobs to the worker over the `jobs`\n\t// channel, then closes it.\n\tfor j := 1; j <= 3; j++ {\n\t\tjobs <- j\n\t\tfmt.Println(\"sent job\", j)\n\t}\n\tclose(jobs)\n\tfmt.Println(\"sent all jobs\")\n\n\t// We await the worker using the\n\t// [synchronization](channel-synchronization) approach\n\t// we saw earlier.\n\t<-done\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-creating-closures-with-anonymous-functions-i":{"intro":"In this challenge, you will learn how to use anonymous functions to create closures in Golang.","steps":[{"title":"Closures","body":["You need to create a function that returns another function. The returned function should increment a variable by one each time it is called. The variable should be unique to each returned function.","• The function intSeq should return another function. • The returned function should increment a variable by one each time it is called. • The variable should be unique to each returned function."],"code":[{"lang":"sh","text":"$ go run closures.go\n1\n2\n3\n1\n\n# The last feature of functions we'll look at for now is\n# recursion."}]}],"commands":["go run closures.go"],"reference":[{"path":"closures.go","text":"// Go supports [_anonymous functions_](https://en.wikipedia.org/wiki/Anonymous_function),\n// which can form <a href=\"https://en.wikipedia.org/wiki/Closure_(computer_science)\"><em>closures</em></a>.\n// Anonymous functions are useful when you want to define\n// a function inline without having to name it.\n\npackage main\n\nimport \"fmt\"\n\n// This function `intSeq` returns another function, which\n// we define anonymously in the body of `intSeq`. The\n// returned function _closes over_ the variable `i` to\n// form a closure.\nfunc intSeq() func() int {\n\ti := 0\n\treturn func() int {\n\t\ti++\n\t\treturn i\n\t}\n}\n\nfunc main() {\n\n\t// We call `intSeq`, assigning the result (a function)\n\t// to `nextInt`. This function value captures its\n\t// own `i` value, which will be updated each time\n\t// we call `nextInt`.\n\tnextInt := intSeq()\n\n\t// See the effect of the closure by calling `nextInt`\n\t// a few times.\n\tfmt.Println(nextInt())\n\tfmt.Println(nextInt())\n\tfmt.Println(nextInt())\n\n\t// To confirm that the state is unique to that\n\t// particular function, create and test a new one.\n\tnewInts := intSeq()\n\tfmt.Println(newInts())\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-command-line-argument-handling-in-go":{"intro":"The purpose of this challenge is to practice working with command-line arguments in Golang.","steps":[{"title":"Command-line arguments","body":["The program currently prints out the raw command-line arguments passed to it. However, it needs to be modified to print out specific arguments based on their index.","• Basic knowledge of Golang • Familiarity with command-line arguments"],"code":[{"lang":"sh","text":"# To experiment with command-line arguments it's best to\n# build a binary with `go build` first.\n$ go build command-line-arguments.go\n$ ./command-line-arguments a b c d\n[./command-line-arguments a b c d]\n[a b c d]\nc\n\n# Next we'll look at more advanced command-line processing\n# with flags."}]}],"commands":["go build command-line-arguments.go"],"reference":[{"path":"command-line-arguments.go","text":"// [_Command-line arguments_](https://en.wikipedia.org/wiki/Command-line_interface#Arguments)\n// are a common way to parameterize execution of programs.\n// For example, `go run hello.go` uses `run` and\n// `hello.go` arguments to the `go` program.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\nfunc main() {\n\n\t// `os.Args` provides access to raw command-line\n\t// arguments. Note that the first value in this slice\n\t// is the path to the program, and `os.Args[1:]`\n\t// holds the arguments to the program.\n\targsWithProg := os.Args\n\targsWithoutProg := os.Args[1:]\n\n\t// You can get individual args with normal indexing.\n\targ := os.Args[3]\n\n\tfmt.Println(argsWithProg)\n\tfmt.Println(argsWithoutProg)\n\tfmt.Println(arg)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-command-line-flag-parsing-in-golang":{"intro":"The purpose of this challenge is to implement a command-line program that supports basic command-line flag parsing using the flag package in Golang.","steps":[{"title":"Command-line flags","body":["Implement a Golang program that parses command-line flags and outputs the parsed options and any trailing positional arguments. The program should support the following flags:","• word: a string flag with a default value of \"foo\". • numb: an integer flag with a default value of 42. • fork: a boolean flag with a default value of false. • svar: a string flag that uses an existing variable declared elsewhere in the program.","• The program should use the flag package to parse command-line flags. • The program should output the parsed options and any trailing positional arguments. • The program should support the word, numb, fork, and svar flags as described above."],"code":[{"lang":"sh","text":"# To experiment with the command-line flags program it's\n# best to first compile it and then run the resulting\n# binary directly.\n$ go build command-line-flags.go\n\n# Try out the built program by first giving it values for\n# all flags.\n$ ./command-line-flags -word=opt -numb=7 -fork -svar=flag\nword: opt\nnumb: 7\nfork: true\nsvar: flag\ntail: []\n\n# Note that if you omit flags they automatically take\n# their default values.\n$ ./command-line-flags -word=opt\nword: opt\nnumb: 42\nfork: false\nsvar: bar\ntail: []\n\n# Trailing positional arguments can be provided after\n# any flags.\n$ ./command-line-flags -word=opt a1 a2 a3\nword: opt\n...\ntail: [a1 a2 a3]\n\n# Note that the `flag` package requires all flags to\n# appear before positional arguments (otherwise the flags\n# will be interpreted as positional arguments).\n$ ./command-line-flags -word=opt a1 a2 a3 -numb=7\nword: opt\nnumb: 42\nfork: false\nsvar: bar\ntail: [a1 a2 a3 -numb=7]\n\n# Use `-h` or `--help` flags to get automatically\n# generated help text for the command-line program.\n$ ./command-line-flags -h\nUsage of ./command-line-flags:\n-fork=false: a bool\n-numb=42: an int\n-svar=\"bar\": a string var\n-word=\"foo\": a string"}]}],"commands":["go build command-line-flags.go"],"reference":[{"path":"command-line-flags.go","text":"// [_Command-line flags_](https://en.wikipedia.org/wiki/Command-line_interface#Command-line_option)\n// are a common way to specify options for command-line\n// programs. For example, in `wc -l` the `-l` is a\n// command-line flag.\n\npackage main\n\n// Go provides a `flag` package supporting basic\n// command-line flag parsing. We'll use this package to\n// implement our example command-line program.\nimport (\n\t\"flag\"\n\t\"fmt\"\n)\n\nfunc main() {\n\n\t// Basic flag declarations are available for string,\n\t// integer, and boolean options. Here we declare a\n\t// string flag `word` with a default value `\"foo\"`\n\t// and a short description. This `flag.String` function\n\t// returns a string pointer (not a string value);\n\t// we'll see how to use this pointer below.\n\twordPtr := flag.String(\"word\", \"foo\", \"a string\")\n\n\t// This declares `numb` and `fork` flags, using a\n\t// similar approach to the `word` flag.\n\tnumbPtr := flag.Int(\"numb\", 42, \"an int\")\n\tforkPtr := flag.Bool(\"fork\", false, \"a bool\")\n\n\t// It's also possible to declare an option that uses an\n\t// existing var declared elsewhere in the program.\n\t// Note that we need to pass in a pointer to the flag\n\t// declaration function.\n\tvar svar string\n\tflag.StringVar(&svar, \"svar\", \"bar\", \"a string var\")\n\n\t// Once all flags are declared, call `flag.Parse()`\n\t// to execute the command-line parsing.\n\tflag.Parse()\n\n\t// Here we'll just dump out the parsed options and\n\t// any trailing positional arguments. Note that we\n\t// need to dereference the pointers with e.g. `*wordPtr`\n\t// to get the actual option values.\n\tfmt.Println(\"word:\", *wordPtr)\n\tfmt.Println(\"numb:\", *numbPtr)\n\tfmt.Println(\"fork:\", *forkPtr)\n\tfmt.Println(\"svar:\", svar)\n\tfmt.Println(\"tail:\", flag.Args())\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-command-line-subcommands":{"intro":"This challenge aims to test your ability to define and use subcommands with their own set of flags in Golang.","steps":[{"title":"Command Line Subcommands","body":["You are required to create a program that supports two subcommands, foo and bar, each with its own set of flags. The foo subcommand should have two flags, enable and name, while the bar subcommand should have one flag, level.","• The program should use the flag package to define and parse flags. • The foo subcommand should have two flags, enable and name, both of type string. • The bar subcommand should have one flag, level, of type int. • The program should print an error message if an invalid subcommand is provided. • The program should print the values of the flags for the subcommand that is invoked."],"code":[{"lang":"sh","text":"$ go build command-line-subcommands.go\n\n# First invoke the foo subcommand.\n$ ./command-line-subcommands foo -enable -name=joe a1 a2\nsubcommand 'foo'\nenable: true\nname: joe\ntail: [a1 a2]\n\n# Now try bar.\n$ ./command-line-subcommands bar -level 8 a1\nsubcommand 'bar'\nlevel: 8\ntail: [a1]\n\n# But bar won't accept foo's flags.\n$ ./command-line-subcommands bar -enable a1\nflag provided but not defined: -enable\nUsage of bar:\n-level int\nlevel\n\n# Next we'll look at environment variables, another common\n# way to parameterize programs."}]}],"commands":["go build command-line-subcommands.go"],"reference":[{"path":"command-line-subcommands.go","text":"// Some command-line tools, like the `go` tool or `git`\n// have many *subcommands*, each with its own set of\n// flags. For example, `go build` and `go get` are two\n// different subcommands of the `go` tool.\n// The `flag` package lets us easily define simple\n// subcommands that have their own flags.\n\npackage main\n\nimport (\n\t\"flag\"\n\t\"fmt\"\n\t\"os\"\n)\n\nfunc main() {\n\n\t// We declare a subcommand using the `NewFlagSet`\n\t// function, and proceed to define new flags specific\n\t// for this subcommand.\n\tfooCmd := flag.NewFlagSet(\"foo\", flag.ExitOnError)\n\tfooEnable := fooCmd.Bool(\"enable\", false, \"enable\")\n\tfooName := fooCmd.String(\"name\", \"\", \"name\")\n\n\t// For a different subcommand we can define different\n\t// supported flags.\n\tbarCmd := flag.NewFlagSet(\"bar\", flag.ExitOnError)\n\tbarLevel := barCmd.Int(\"level\", 0, \"level\")\n\n\t// The subcommand is expected as the first argument\n\t// to the program.\n\tif len(os.Args) < 2 {\n\t\tfmt.Println(\"expected 'foo' or 'bar' subcommands\")\n\t\tos.Exit(1)\n\t}\n\n\t// Check which subcommand is invoked.\n\tswitch os.Args[1] {\n\n\t// For every subcommand, we parse its own flags and\n\t// have access to trailing positional arguments.\n\tcase \"foo\":\n\t\tfooCmd.Parse(os.Args[2:])\n\t\tfmt.Println(\"subcommand 'foo'\")\n\t\tfmt.Println(\"  enable:\", *fooEnable)\n\t\tfmt.Println(\"  name:\", *fooName)\n\t\tfmt.Println(\"  tail:\", fooCmd.Args())\n\tcase \"bar\":\n\t\tbarCmd.Parse(os.Args[2:])\n\t\tfmt.Println(\"subcommand 'bar'\")\n\t\tfmt.Println(\"  level:\", *barLevel)\n\t\tfmt.Println(\"  tail:\", barCmd.Args())\n\tdefault:\n\t\tfmt.Println(\"expected 'foo' or 'bar' subcommands\")\n\t\tos.Exit(1)\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-constants-programming-challenge":{"intro":"This challenge aims to test your understanding of constants in Golang.","steps":[{"title":"Constants","body":["The problem to be solved is to demonstrate the use of constants in Golang for character, string, boolean, and numeric values.","The Challenge has the following requirements:","• Use the const keyword to declare a constant value. • Constants should be of character, string, boolean, and numeric values. • A constant statement can appear anywhere a var statement can. • Demonstrate that constant expressions perform arithmetic with arbitrary precision. • A numeric constant has no type until it's given one, such as by an explicit conversion. • A number can be given a type by using it in a context that requires one, such as a variable assignment or function call."],"code":[{"lang":"sh","text":"$ go run constant.go\nconstant\n6e+11\n600000000000\n-0.28470407323754404"}]}],"commands":["go run constant.go"],"reference":[{"path":"constants.go","text":"// Go supports _constants_ of character, string, boolean,\n// and numeric values.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math\"\n)\n\n// `const` declares a constant value.\nconst s string = \"constant\"\n\nfunc main() {\n\tfmt.Println(s)\n\n\t// A `const` statement can appear anywhere a `var`\n\t// statement can.\n\tconst n = 500000000\n\n\t// Constant expressions perform arithmetic with\n\t// arbitrary precision.\n\tconst d = 3e20 / n\n\tfmt.Println(d)\n\n\t// A numeric constant has no type until it's given\n\t// one, such as by an explicit conversion.\n\tfmt.Println(int64(d))\n\n\t// A number can be given a type by using it in a\n\t// context that requires one, such as a variable\n\t// assignment or function call. For example, here\n\t// `math.Sin` expects a `float64`.\n\tfmt.Println(math.Sin(n))\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-context-cancellation-demonstration":{"intro":"This challenge aims to demonstrate the usage of context.Context for controlling cancellation in Golang. A Context carries deadlines, cancellation signals, and other request-scoped values across API boundaries and goroutines.","steps":[{"title":"Context","body":["The hello function simulates some work the server is doing by waiting for a few seconds before sending a reply to the client. While working, keep an eye on the context's Done() channel for a signal that we should cancel the work and return as soon as possible.","• Golang version 1.13 or higher."],"code":[{"lang":"sh","text":"# Run the server in the background.\n$ go run context-in-http-servers.go &\n\n# Simulate a client request to `/hello`, hitting\n# Ctrl+C shortly after starting to signal\n# cancellation.\n$ curl localhost:8090/hello\nserver: hello handler started\n^C\nserver: context canceled\nserver: hello handler ended"}]}],"commands":["go run context-in-http-servers.go &","curl localhost:8090/hello"],"reference":[{"path":"context.go","text":"// In the previous example we looked at setting up a simple\n// [HTTP server](http-servers). HTTP servers are useful for\n// demonstrating the usage of `context.Context` for\n// controlling cancellation. A `Context` carries deadlines,\n// cancellation signals, and other request-scoped values\n// across API boundaries and goroutines.\npackage main\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n\t\"time\"\n)\n\nfunc hello(w http.ResponseWriter, req *http.Request) {\n\n\t// A `context.Context` is created for each request by\n\t// the `net/http` machinery, and is available with\n\t// the `Context()` method.\n\tctx := req.Context()\n\tfmt.Println(\"server: hello handler started\")\n\tdefer fmt.Println(\"server: hello handler ended\")\n\n\t// Wait for a few seconds before sending a reply to the\n\t// client. This could simulate some work the server is\n\t// doing. While working, keep an eye on the context's\n\t// `Done()` channel for a signal that we should cancel\n\t// the work and return as soon as possible.\n\tselect {\n\tcase <-time.After(10 * time.Second):\n\t\tfmt.Fprintf(w, \"hello\\n\")\n\tcase <-ctx.Done():\n\t\t// The context's `Err()` method returns an error\n\t\t// that explains why the `Done()` channel was\n\t\t// closed.\n\t\terr := ctx.Err()\n\t\tfmt.Println(\"server:\", err)\n\t\tinternalError := http.StatusInternalServerError\n\t\thttp.Error(w, err.Error(), internalError)\n\t}\n}\n\nfunc main() {\n\n\t// As before, we register our handler on the \"/hello\"\n\t// route, and start serving.\n\thttp.HandleFunc(\"/hello\", hello)\n\thttp.ListenAndServe(\":8090\", nil)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-deferred-function-execution-cleanup":{"intro":"In this challenge, you need to use the defer statement to ensure that a file is properly created, written to, and closed, even if errors occur during the execution of the functions.","steps":[{"title":"Defer","body":["In this challenge, you need to use defer to create a file, write to it, and then close it when you're done.","• The createFile function should create a file with the given path and return a pointer to the file. • The writeFile function should write the string \"data\" to the file. • The closeFile function should close the file and check for errors."],"code":[{"lang":"sh","text":"# Running the program confirms that the file is closed\n# after being written.\n$ go run defer.go\ncreating\nwriting\nclosing"}]}],"commands":["go run defer.go"],"reference":[{"path":"defer.go","text":"// _Defer_ is used to ensure that a function call is\n// performed later in a program's execution, usually for\n// purposes of cleanup. `defer` is often used where e.g.\n// `ensure` and `finally` would be used in other languages.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\n// Suppose we wanted to create a file, write to it,\n// and then close when we're done. Here's how we could\n// do that with `defer`.\nfunc main() {\n\n\t// Immediately after getting a file object with\n\t// `createFile`, we defer the closing of that file\n\t// with `closeFile`. This will be executed at the end\n\t// of the enclosing function (`main`), after\n\t// `writeFile` has finished.\n\tf := createFile(\"/tmp/defer.txt\")\n\tdefer closeFile(f)\n\twriteFile(f)\n}\n\nfunc createFile(p string) *os.File {\n\tfmt.Println(\"creating\")\n\tf, err := os.Create(p)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn f\n}\n\nfunc writeFile(f *os.File) {\n\tfmt.Println(\"writing\")\n\tfmt.Fprintln(f, \"data\")\n\n}\n\nfunc closeFile(f *os.File) {\n\tfmt.Println(\"closing\")\n\terr := f.Close()\n\t// It's important to check for errors when closing a\n\t// file, even in a deferred function.\n\tif err != nil {\n\t\tfmt.Fprintf(os.Stderr, \"error: %v\\n\", err)\n\t\tos.Exit(1)\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-working-with-directories-in-go":{"intro":"In this challenge, you will learn how to work with directories in Go. Go provides several useful functions for working with directories in the file system.","steps":[{"title":"Directories","body":["Create a Go program that creates a new sub-directory in the current working directory, creates a hierarchy of directories, including parents, lists directory contents, changes the current working directory, and visits a directory recursively.","• Create a new sub-directory in the current working directory. • When creating temporary directories, it's good practice to defer their removal. os.RemoveAll will delete a whole directory tree (similarly to rm -rf). • Create a hierarchy of directories, including parents with MkdirAll. This is similar to the command-line mkdir -p. • ReadDir lists directory contents, returning a slice of os.DirEntry objects. • Chdir lets us change the current working directory, similarly to cd. • Visit a directory recursively, including all its sub-directories. Walk accepts a callback function to handle every file or directory visited."],"code":[{"lang":"sh","text":"$ go run directories.go\nListing subdir/parent\nchild true\nfile2 false\nfile3 false\nListing subdir/parent/child\nfile4 false\nVisiting subdir\nsubdir true\nsubdir/file1 false\nsubdir/parent true\nsubdir/parent/child true\nsubdir/parent/child/file4 false\nsubdir/parent/file2 false\nsubdir/parent/file3 false"}]}],"commands":["go run directories.go"],"reference":[{"path":"directories.go","text":"// Go has several useful functions for working with\n// *directories* in the file system.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"path/filepath\"\n)\n\nfunc check(e error) {\n\tif e != nil {\n\t\tpanic(e)\n\t}\n}\n\nfunc main() {\n\n\t// Create a new sub-directory in the current working\n\t// directory.\n\terr := os.Mkdir(\"subdir\", 0755)\n\tcheck(err)\n\n\t// When creating temporary directories, it's good\n\t// practice to `defer` their removal. `os.RemoveAll`\n\t// will delete a whole directory tree (similarly to\n\t// `rm -rf`).\n\tdefer os.RemoveAll(\"subdir\")\n\n\t// Helper function to create a new empty file.\n\tcreateEmptyFile := func(name string) {\n\t\td := []byte(\"\")\n\t\tcheck(os.WriteFile(name, d, 0644))\n\t}\n\n\tcreateEmptyFile(\"subdir/file1\")\n\n\t// We can create a hierarchy of directories, including\n\t// parents with `MkdirAll`. This is similar to the\n\t// command-line `mkdir -p`.\n\terr = os.MkdirAll(\"subdir/parent/child\", 0755)\n\tcheck(err)\n\n\tcreateEmptyFile(\"subdir/parent/file2\")\n\tcreateEmptyFile(\"subdir/parent/file3\")\n\tcreateEmptyFile(\"subdir/parent/child/file4\")\n\n\t// `ReadDir` lists directory contents, returning a\n\t// slice of `os.DirEntry` objects.\n\tc, err := os.ReadDir(\"subdir/parent\")\n\tcheck(err)\n\n\tfmt.Println(\"Listing subdir/parent\")\n\tfor _, entry := range c {\n\t\tfmt.Println(\" \", entry.Name(), entry.IsDir())\n\t}\n\n\t// `Chdir` lets us change the current working directory,\n\t// similarly to `cd`.\n\terr = os.Chdir(\"subdir/parent/child\")\n\tcheck(err)\n\n\t// Now we'll see the contents of `subdir/parent/child`\n\t// when listing the *current* directory.\n\tc, err = os.ReadDir(\".\")\n\tcheck(err)\n\n\tfmt.Println(\"Listing subdir/parent/child\")\n\tfor _, entry := range c {\n\t\tfmt.Println(\" \", entry.Name(), entry.IsDir())\n\t}\n\n\t// `cd` back to where we started.\n\terr = os.Chdir(\"../../..\")\n\tcheck(err)\n\n\t// We can also visit a directory *recursively*,\n\t// including all its sub-directories. `Walk` accepts\n\t// a callback function to handle every file or\n\t// directory visited.\n\tfmt.Println(\"Visiting subdir\")\n\terr = filepath.Walk(\"subdir\", visit)\n}\n\n// `visit` is called for every file or directory found\n// recursively by `filepath.Walk`.\nfunc visit(p string, info os.FileInfo, err error) error {\n\tif err != nil {\n\t\treturn err\n\t}\n\tfmt.Println(\" \", p, info.IsDir())\n\treturn nil\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-embedding-files-in-go-programs":{"intro":"This challenge aims to test your understanding of the embed package in Golang. The embed package allows programs to include arbitrary files and folders in the Go binary at build time.","steps":[{"title":"Embed Directive","body":["Your task is to modify the given code to embed files and folders into the Go binary and print their contents.","• You must use the embed package to embed files and folders. • You must use the string and []byte types to store the contents of the embedded files. • You must use the embed.FS type to embed multiple files or folders with wildcards. • You must print the contents of the embedded files."],"code":[{"lang":"sh","text":"# Use these commands to run the example.\n# (Note: due to limitation on go playground,\n# this example can only be run on your local machine.)\n$ mkdir -p folder\n$ echo \"hello go\" > folder/single_file.txt\n$ echo \"123\" > folder/file1.hash\n$ echo \"456\" > folder/file2.hash\n\n$ go run embed-directive.go\nhello go\nhello go\n123\n456"}]}],"commands":["mkdir -p folder","echo \"hello go\" > folder/single_file.txt","echo \"123\" > folder/file1.hash","echo \"456\" > folder/file2.hash","go run embed-directive.go"],"reference":[{"path":"embed-directive.go","text":"// `//go:embed` is a [compiler\n// directive](https://pkg.go.dev/cmd/compile#hdr-Compiler_Directives) that\n// allows programs to include arbitrary files and folders in the Go binary at\n// build time. Read more about the embed directive\n// [here](https://pkg.go.dev/embed).\npackage main\n\n// Import the `embed` package; if you don't use any exported\n// identifiers from this package, you can do a blank import with `_ \"embed\"`.\nimport (\n\t\"embed\"\n)\n\n// `embed` directives accept paths relative to the directory containing the\n// Go source file. This directive embeds the contents of the file into the\n// `string` variable immediately following it.\n//\n//go:embed folder/single_file.txt\nvar fileString string\n\n// Or embed the contents of the file into a `[]byte`.\n//\n//go:embed folder/single_file.txt\nvar fileByte []byte\n\n// We can also embed multiple files or even folders with wildcards. This uses\n// a variable of the [embed.FS type](https://pkg.go.dev/embed#FS), which\n// implements a simple virtual file system.\n//\n//go:embed folder/single_file.txt\n//go:embed folder/*.hash\nvar folder embed.FS\n\nfunc main() {\n\n\t// Print out the contents of `single_file.txt`.\n\tprint(fileString)\n\tprint(string(fileByte))\n\n\t// Retrieve some files from the embedded folder.\n\tcontent1, _ := folder.ReadFile(\"folder/file1.hash\")\n\tprint(string(content1))\n\n\tcontent2, _ := folder.ReadFile(\"folder/file2.hash\")\n\tprint(string(content2))\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-unix-environment-variables":{"intro":"This challenge will cover the basics of environment variables in Unix programs. Environment variables are used to convey configuration information to programs.","steps":[{"title":"Environment Variables","body":[],"code":[{"lang":"sh","text":"# Running the program shows that we pick up the value\n# for `FOO` that we set in the program, but that\n# `BAR` is empty.\n$ go run environment-variables.go\nFOO: 1\nBAR:\n\n# The list of keys in the environment will depend on your\n# particular machine.\nTERM_PROGRAM\nPATH\nSHELL\n...\nFOO\n\n# If we set `BAR` in the environment first, the running\n# program picks that value up.\n$ BAR=2 go run environment-variables.go\nFOO: 1\nBAR: 2\n..."}]}],"commands":["go run environment-variables.go"],"reference":[{"path":"environment-variables.go","text":"// [Environment variables](https://en.wikipedia.org/wiki/Environment_variable)\n// are a universal mechanism for [conveying configuration\n// information to Unix programs](https://www.12factor.net/config).\n// Let's look at how to set, get, and list environment variables.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"strings\"\n)\n\nfunc main() {\n\n\t// To set a key/value pair, use `os.Setenv`. To get a\n\t// value for a key, use `os.Getenv`. This will return\n\t// an empty string if the key isn't present in the\n\t// environment.\n\tos.Setenv(\"FOO\", \"1\")\n\tfmt.Println(\"FOO:\", os.Getenv(\"FOO\"))\n\tfmt.Println(\"BAR:\", os.Getenv(\"BAR\"))\n\n\t// Use `os.Environ` to list all key/value pairs in the\n\t// environment. This returns a slice of strings in the\n\t// form `KEY=value`. You can `strings.SplitN` them to\n\t// get the key and value. Here we print all the keys.\n\tfmt.Println()\n\tfor _, e := range os.Environ() {\n\t\tpair := strings.SplitN(e, \"=\", 2)\n\t\tfmt.Println(pair[0])\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-epoch-time":{"intro":"The Epoch challenge is a Golang challenge that aims to test your ability to get the number of seconds, milliseconds, or nanoseconds since the Unix epoch.","steps":[{"title":"Epoch","body":["The problem to be solved in this challenge is to write a Golang program that can calculate the number of seconds, milliseconds, or nanoseconds since the Unix epoch.","To complete this challenge, you need to have a basic understanding of Golang and the following requirements:","• Familiarity with the time package in Golang. • Knowledge of how to use the Unix, UnixMilli, and UnixNano functions in the time package."],"code":[{"lang":"sh","text":"$ go run epoch.go\n2012-10-31 16:13:58.292387 +0000 UTC\n1351700038\n1351700038292\n1351700038292387000\n2012-10-31 16:13:58 +0000 UTC\n2012-10-31 16:13:58.292387 +0000 UTC\n\n# Next we'll look at another time-related task: time\n# parsing and formatting."}]}],"commands":["go run epoch.go"],"reference":[{"path":"epoch.go","text":"// A common requirement in programs is getting the number\n// of seconds, milliseconds, or nanoseconds since the\n// [Unix epoch](https://en.wikipedia.org/wiki/Unix_time).\n// Here's how to do it in Go.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n\n\t// Use `time.Now` with `Unix`, `UnixMilli` or `UnixNano`\n\t// to get elapsed time since the Unix epoch in seconds,\n\t// milliseconds or nanoseconds, respectively.\n\tnow := time.Now()\n\tfmt.Println(now)\n\n\tfmt.Println(now.Unix())\n\tfmt.Println(now.UnixMilli())\n\tfmt.Println(now.UnixNano())\n\n\t// You can also convert integer seconds or nanoseconds\n\t// since the epoch into the corresponding `time`.\n\tfmt.Println(time.Unix(now.Unix(), 0))\n\tfmt.Println(time.Unix(0, now.UnixNano()))\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-handling-errors-in-golang":{"intro":"The purpose of this challenge is to understand how to handle errors in Golang.","steps":[{"title":"Errors","body":["The challenge provides two functions that return an error if the input argument is 42. The first function returns a basic error value, while the second function uses a custom type to represent the error.","• The errors package must be imported. • The f1 function must return an error if the input argument is 42. • The f2 function must return an error of type argError if the input argument is 42. • The argError type must have two fields: arg and prob. • The argError type must implement the Error() method. • The main function must call both f1 and f2 with input arguments of 7 and 42. • The main function must print the result of each function call, along with any error that was returned. • The main function must demonstrate how to programmatically use the data in a custom error."],"code":[{"lang":"sh","text":"# See this [great post](https://go.dev/blog/error-handling-and-go)\n# on the Go blog for more on error handling."}]}],"commands":[],"reference":[{"path":"errors.go","text":"// In Go it's idiomatic to communicate errors via an\n// explicit, separate return value. This contrasts with\n// the exceptions used in languages like Java and Ruby and\n// the overloaded single result / error value sometimes\n// used in C. Go's approach makes it easy to see which\n// functions return errors and to handle them using the\n// same language constructs employed for any other,\n// non-error tasks.\n\npackage main\n\nimport (\n\t\"errors\"\n\t\"fmt\"\n)\n\n// By convention, errors are the last return value and\n// have type `error`, a built-in interface.\nfunc f1(arg int) (int, error) {\n\tif arg == 42 {\n\n\t\t// `errors.New` constructs a basic `error` value\n\t\t// with the given error message.\n\t\treturn -1, errors.New(\"can't work with 42\")\n\n\t}\n\n\t// A `nil` value in the error position indicates that\n\t// there was no error.\n\treturn arg + 3, nil\n}\n\n// It's possible to use custom types as `error`s by\n// implementing the `Error()` method on them. Here's a\n// variant on the example above that uses a custom type\n// to explicitly represent an argument error.\ntype argError struct {\n\targ  int\n\tprob string\n}\n\nfunc (e *argError) Error() string {\n\treturn fmt.Sprintf(\"%d - %s\", e.arg, e.prob)\n}\n\nfunc f2(arg int) (int, error) {\n\tif arg == 42 {\n\n\t\t// In this case we use `&argError` syntax to build\n\t\t// a new struct, supplying values for the two\n\t\t// fields `arg` and `prob`.\n\t\treturn -1, &argError{arg, \"can't work with it\"}\n\t}\n\treturn arg + 3, nil\n}\n\nfunc main() {\n\n\t// The two loops below test out each of our\n\t// error-returning functions. Note that the use of an\n\t// inline error check on the `if` line is a common\n\t// idiom in Go code.\n\tfor _, i := range []int{7, 42} {\n\t\tif r, e := f1(i); e != nil {\n\t\t\tfmt.Println(\"f1 failed:\", e)\n\t\t} else {\n\t\t\tfmt.Println(\"f1 worked:\", r)\n\t\t}\n\t}\n\tfor _, i := range []int{7, 42} {\n\t\tif r, e := f2(i); e != nil {\n\t\t\tfmt.Println(\"f2 failed:\", e)\n\t\t} else {\n\t\t\tfmt.Println(\"f2 worked:\", r)\n\t\t}\n\t}\n\n\t// If you want to programmatically use the data in\n\t// a custom error, you'll need to get the error as an\n\t// instance of the custom error type via type\n\t// assertion.\n\t_, e := f2(42)\n\tif ae, ok := e.(*argError); ok {\n\t\tfmt.Println(ae.arg)\n\t\tfmt.Println(ae.prob)\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-replacing-go-process-with-exec-function":{"intro":"This challenge focuses on replacing the current Go process with another process using Go's implementation of the classic exec function.","steps":[{"title":"Execing Processes","body":["The problem is to replace the current Go process with another process, such as a non-Go process."],"code":[{"lang":"sh","text":"# When we run our program it is replaced by `ls`.\n$ go run execing-processes.go\ntotal 16\ndrwxr-xr-x 4 mark 136B Oct 3 16:29 .\ndrwxr-xr-x 91 mark 3.0K Oct 3 12:50 ..\n-rw-r--r-- 1 mark 1.3K Oct 3 16:28 execing-processes.go\n\n# Note that Go does not offer a classic Unix `fork`\n# function. Usually this isn't an issue though, since\n# starting goroutines, spawning processes, and exec'ing\n# processes covers most use cases for `fork`."}]}],"commands":["go run execing-processes.go"],"reference":[{"path":"execing-processes.go","text":"// In the previous example we looked at\n// [spawning external processes](spawning-processes). We\n// do this when we need an external process accessible to\n// a running Go process. Sometimes we just want to\n// completely replace the current Go process with another\n// (perhaps non-Go) one. To do this we'll use Go's\n// implementation of the classic\n// <a href=\"https://en.wikipedia.org/wiki/Exec_(operating_system)\"><code>exec</code></a>\n// function.\n\npackage main\n\nimport (\n\t\"os\"\n\t\"os/exec\"\n\t\"syscall\"\n)\n\nfunc main() {\n\n\t// For our example we'll exec `ls`. Go requires an\n\t// absolute path to the binary we want to execute, so\n\t// we'll use `exec.LookPath` to find it (probably\n\t// `/bin/ls`).\n\tbinary, lookErr := exec.LookPath(\"ls\")\n\tif lookErr != nil {\n\t\tpanic(lookErr)\n\t}\n\n\t// `Exec` requires arguments in slice form (as\n\t// opposed to one big string). We'll give `ls` a few\n\t// common arguments. Note that the first argument should\n\t// be the program name.\n\targs := []string{\"ls\", \"-a\", \"-l\", \"-h\"}\n\n\t// `Exec` also needs a set of [environment variables](environment-variables)\n\t// to use. Here we just provide our current\n\t// environment.\n\tenv := os.Environ()\n\n\t// Here's the actual `syscall.Exec` call. If this call is\n\t// successful, the execution of our process will end\n\t// here and be replaced by the `/bin/ls -a -l -h`\n\t// process. If there is an error we'll get a return\n\t// value.\n\texecErr := syscall.Exec(binary, args, env)\n\tif execErr != nil {\n\t\tpanic(execErr)\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-exit-challenge-in-go":{"intro":"The Exit challenge is designed to test your ability to use the os.Exit function in Go to immediately exit with a given status.","steps":[{"title":"Exit","body":["The problem to be solved in this challenge is to exit a Go program with a specific status code using the os.Exit function.","To complete this challenge, you will need to have a basic understanding of Go programming and the os package."],"code":[{"lang":"sh","text":"#  If you run `exit.go` using `go run`, the exit\n# will be picked up by `go` and printed.\n$ go run exit.go\nexit status 3\n\n# By building and executing a binary you can see\n# the status in the terminal.\n$ go build exit.go\n$ ./exit\n$ echo $?\n3\n\n# Note that the `!` from our program never got printed."}]}],"commands":["go run exit.go","go build exit.go","echo $?"],"reference":[{"path":"exit.go","text":"// Use `os.Exit` to immediately exit with a given\n// status.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\nfunc main() {\n\n\t// `defer`s will _not_ be run when using `os.Exit`, so\n\t// this `fmt.Println` will never be called.\n\tdefer fmt.Println(\"!\")\n\n\t// Exit with status 3.\n\tos.Exit(3)\n}\n\n// Note that unlike e.g. C, Go does not use an integer\n// return value from `main` to indicate exit status. If\n// you'd like to exit with a non-zero status you should\n// use `os.Exit`."}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-file-path-handling-in-golang":{"intro":"The filepath package in Golang provides functions to parse and construct file paths in a way that is portable between operating systems.","steps":[{"title":"File Paths","body":["In this challenge, you need to use the filepath package to perform various operations on file paths, such as constructing paths in a portable way, splitting a path into directory and file components, checking whether a path is absolute, finding the extension of a file, and finding a relative path between two paths.","• Use Join to construct paths in a portable way. • Use Dir and Base to split a path into directory and file components. • Use IsAbs to check whether a path is absolute. • Use Ext to find the extension of a file. • Use TrimSuffix to remove the extension from a file name. • Use Rel to find a relative path between two paths."],"code":[{"lang":"sh","text":"$ go run file-paths.go\np: dir1/dir2/filename\ndir1/filename\ndir1/filename\nDir(p): dir1/dir2\nBase(p): filename\nfalse\ntrue\n.json\nconfig\nt/file\n../c/t/file"}]}],"commands":["go run file-paths.go"],"reference":[{"path":"file-paths.go","text":"// The `filepath` package provides functions to parse\n// and construct *file paths* in a way that is portable\n// between operating systems; `dir/file` on Linux vs.\n// `dir\\file` on Windows, for example.\npackage main\n\nimport (\n\t\"fmt\"\n\t\"path/filepath\"\n\t\"strings\"\n)\n\nfunc main() {\n\n\t// `Join` should be used to construct paths in a\n\t// portable way. It takes any number of arguments\n\t// and constructs a hierarchical path from them.\n\tp := filepath.Join(\"dir1\", \"dir2\", \"filename\")\n\tfmt.Println(\"p:\", p)\n\n\t// You should always use `Join` instead of\n\t// concatenating `/`s or `\\`s manually. In addition\n\t// to providing portability, `Join` will also\n\t// normalize paths by removing superfluous separators\n\t// and directory changes.\n\tfmt.Println(filepath.Join(\"dir1//\", \"filename\"))\n\tfmt.Println(filepath.Join(\"dir1/../dir1\", \"filename\"))\n\n\t// `Dir` and `Base` can be used to split a path to the\n\t// directory and the file. Alternatively, `Split` will\n\t// return both in the same call.\n\tfmt.Println(\"Dir(p):\", filepath.Dir(p))\n\tfmt.Println(\"Base(p):\", filepath.Base(p))\n\n\t// We can check whether a path is absolute.\n\tfmt.Println(filepath.IsAbs(\"dir/file\"))\n\tfmt.Println(filepath.IsAbs(\"/dir/file\"))\n\n\tfilename := \"config.json\"\n\n\t// Some file names have extensions following a dot. We\n\t// can split the extension out of such names with `Ext`.\n\text := filepath.Ext(filename)\n\tfmt.Println(ext)\n\n\t// To find the file's name with the extension removed,\n\t// use `strings.TrimSuffix`.\n\tfmt.Println(strings.TrimSuffix(filename, ext))\n\n\t// `Rel` finds a relative path between a *base* and a\n\t// *target*. It returns an error if the target cannot\n\t// be made relative to base.\n\trel, err := filepath.Rel(\"a/b\", \"a/b/t/file\")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tfmt.Println(rel)\n\n\trel, err = filepath.Rel(\"a/b\", \"a/c/t/file\")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tfmt.Println(rel)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-for-loop":{"intro":"This challenge aims to test your understanding of the for loop in Golang.","steps":[{"title":"For","body":["The code below contains different types of for loops. However, some parts of the code are incomplete, and you need to fill in the blanks to make the code work correctly.","• Basic knowledge of Golang syntax • Familiarity with for loops in Golang"],"code":[{"lang":"sh","text":"$ go run for.go\n1\n2\n3\n7\n8\n9\nloop\n1\n3\n5\n\n# We'll see some other `for` forms later when we look at\n# `range` statements, channels, and other data\n# structures."}]}],"commands":["go run for.go"],"reference":[{"path":"for.go","text":"// `for` is Go's only looping construct. Here are\n// some basic types of `for` loops.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// The most basic type, with a single condition.\n\ti := 1\n\tfor i <= 3 {\n\t\tfmt.Println(i)\n\t\ti = i + 1\n\t}\n\n\t// A classic initial/condition/after `for` loop.\n\tfor j := 7; j <= 9; j++ {\n\t\tfmt.Println(j)\n\t}\n\n\t// `for` without a condition will loop repeatedly\n\t// until you `break` out of the loop or `return` from\n\t// the enclosing function.\n\tfor {\n\t\tfmt.Println(\"loop\")\n\t\tbreak\n\t}\n\n\t// You can also `continue` to the next iteration of\n\t// the loop.\n\tfor n := 0; n <= 5; n++ {\n\t\tif n%2 == 0 {\n\t\t\tcontinue\n\t\t}\n\t\tfmt.Println(n)\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-functions-fundamentals":{"intro":"In this challenge, we will learn about functions in Go. We will see how to define functions, how to pass arguments to them, and how to return values from them.","steps":[{"title":"Functions","body":["In the given code, we have two functions plus and plusPlus. The plus function takes two integers as arguments and returns their sum. The plusPlus function takes three integers as arguments and returns their sum. Your task is to complete the plusPlus function by adding the third integer to the sum of the first two integers.","• The plus function should take two integers as arguments and return their sum as an integer. • The plusPlus function should take three integers as arguments and return their sum as an integer. • The plusPlus function should use the plus function to calculate the sum of the first two integers."],"code":[{"lang":"sh","text":"$ go run functions.go\n1+2 = 3\n1+2+3 = 6\n\n# There are several other features to Go functions. One is\n# multiple return values, which we'll look at next."}]}],"commands":["go run functions.go"],"reference":[{"path":"functions.go","text":"// _Functions_ are central in Go. We'll learn about\n// functions with a few different examples.\n\npackage main\n\nimport \"fmt\"\n\n// Here's a function that takes two `int`s and returns\n// their sum as an `int`.\nfunc plus(a int, b int) int {\n\n\t// Go requires explicit returns, i.e. it won't\n\t// automatically return the value of the last\n\t// expression.\n\treturn a + b\n}\n\n// When you have multiple consecutive parameters of\n// the same type, you may omit the type name for the\n// like-typed parameters up to the final parameter that\n// declares the type.\nfunc plusPlus(a, b, c int) int {\n\treturn a + b + c\n}\n\nfunc main() {\n\n\t// Call a function just as you'd expect, with\n\t// `name(args)`.\n\tres := plus(1, 2)\n\tfmt.Println(\"1+2 =\", res)\n\n\tres = plusPlus(1, 2, 3)\n\tfmt.Println(\"1+2+3 =\", res)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-generics-introduction":{"intro":"This challenge introduces the concept of generics in Golang. Starting from version 1.18, Golang has added support for generics, which allows us to write more flexible and reusable code.","steps":[{"title":"Generics","body":["The problem to be solved in this challenge is to understand how to define and use generic functions and types in Golang.","• Understand the concept of generics in Golang. • Know how to define generic functions with type parameters and constraints. • Know how to define generic types with type parameters. • Understand how to define methods on generic types. • Know how to invoke generic functions with type inference."],"code":[{"lang":"sh","text":"$ go run generics.go\nkeys: [4 1 2]\nlist: [10 13 23]"}]}],"commands":["go run generics.go"],"reference":[{"path":"generics.go","text":"// Starting with version 1.18, Go has added support for\n// _generics_, also known as _type parameters_.\n\npackage main\n\nimport \"fmt\"\n\n// As an example of a generic function, `MapKeys` takes\n// a map of any type and returns a slice of its keys.\n// This function has two type parameters - `K` and `V`;\n// `K` has the `comparable` _constraint_, meaning that\n// we can compare values of this type with the `==` and\n// `!=` operators. This is required for map keys in Go.\n// `V` has the `any` constraint, meaning that it's not\n// restricted in any way (`any` is an alias for `interface{}`).\nfunc MapKeys[K comparable, V any](m map[K]V) []K {\n\tr := make([]K, 0, len(m))\n\tfor k := range m {\n\t\tr = append(r, k)\n\t}\n\treturn r\n}\n\n// As an example of a generic type, `List` is a\n// singly-linked list with values of any type.\ntype List[T any] struct {\n\thead, tail *element[T]\n}\n\ntype element[T any] struct {\n\tnext *element[T]\n\tval  T\n}\n\n// We can define methods on generic types just like we\n// do on regular types, but we have to keep the type\n// parameters in place. The type is `List[T]`, not `List`.\nfunc (lst *List[T]) Push(v T) {\n\tif lst.tail == nil {\n\t\tlst.head = &element[T]{val: v}\n\t\tlst.tail = lst.head\n\t} else {\n\t\tlst.tail.next = &element[T]{val: v}\n\t\tlst.tail = lst.tail.next\n\t}\n}\n\nfunc (lst *List[T]) GetAll() []T {\n\tvar elems []T\n\tfor e := lst.head; e != nil; e = e.next {\n\t\telems = append(elems, e.val)\n\t}\n\treturn elems\n}\n\nfunc main() {\n\tvar m = map[int]string{1: \"2\", 2: \"4\", 4: \"8\"}\n\n\t// When invoking generic functions, we can often rely\n\t// on _type inference_. Note that we don't have to\n\t// specify the types for `K` and `V` when\n\t// calling `MapKeys` - the compiler infers them\n\t// automatically.\n\tfmt.Println(\"keys:\", MapKeys(m))\n\n\t// ... though we could also specify them explicitly.\n\t_ = MapKeys[int, string](m)\n\n\tlst := List[int]{}\n\tlst.Push(10)\n\tlst.Push(13)\n\tlst.Push(23)\n\tfmt.Println(\"list:\", lst.GetAll())\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-concurrent-goroutines-in-golang":{"intro":"This challenge is designed to test your understanding of goroutines in Golang. Goroutines are lightweight threads of execution that allow for concurrent execution of functions.","steps":[{"title":"Goroutines","body":["The problem to be solved in this challenge is to create and run goroutines to execute functions concurrently.","• The f function should print out its input string and a counter variable three times. • The main function should call the f function synchronously and print out \"direct\" and a counter variable three times. • The main function should call the f function asynchronously using a goroutine and print out \"goroutine\" and a counter variable three times. • The main function should start a goroutine to execute an anonymous function that prints out a message. • The main function should wait for the goroutines to finish executing before printing out \"done\"."],"code":[{"lang":"sh","text":"# When we run this program, we see the output of the\n# blocking call first, then the output of the two\n# goroutines. The goroutines' output may be interleaved,\n# because goroutines are being run concurrently by the\n# Go runtime.\n\n# Next we'll look at a complement to goroutines in\n# concurrent Go programs: channels."}]}],"commands":[],"reference":[{"path":"goroutines.go","text":"// A _goroutine_ is a lightweight thread of execution.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc f(from string) {\n\tfor i := 0; i < 3; i++ {\n\t\tfmt.Println(from, \":\", i)\n\t}\n}\n\nfunc main() {\n\n\t// Suppose we have a function call `f(s)`. Here's how\n\t// we'd call that in the usual way, running it\n\t// synchronously.\n\tf(\"direct\")\n\n\t// To invoke this function in a goroutine, use\n\t// `go f(s)`. This new goroutine will execute\n\t// concurrently with the calling one.\n\tgo f(\"goroutine\")\n\n\t// You can also start a goroutine for an anonymous\n\t// function call.\n\tgo func(msg string) {\n\t\tfmt.Println(msg)\n\t}(\"going\")\n\n\t// Our two function calls are running asynchronously in\n\t// separate goroutines now. Wait for them to finish\n\t// (for a more robust approach, use a [WaitGroup](waitgroups)).\n\ttime.Sleep(time.Second)\n\tfmt.Println(\"done\")\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-hello-world-golang":{"intro":"This Golang challenge aims to test your basic understanding of the language syntax and structure. You will be required to write a simple program that prints the classic 'hello world' message.","steps":[{"title":"Hello World","body":["Write a program that prints the message \"hello world\" to the console.","• The program should use the fmt package to print the message. • The program should be written in Golang."],"code":[{"lang":"sh","text":"# To run the program, put the code in `hello-world.go` and\n# use `go run`.\n$ go run hello-world.go\nhello world\n\n# Sometimes we'll want to build our programs into\n# binaries. We can do this using `go build`.\n$ go build hello-world.go\n$ ls\nhello-world hello-world.go\n\n# We can then execute the built binary directly.\n$ ./hello-world\nhello world\n\n# Now that we can run and build basic Go programs, let's\n# learn more about the language."}]}],"commands":["go run hello-world.go","go build hello-world.go"],"reference":[{"path":"hello-world.go","text":"// Our first program will print the classic \"hello world\"\n// message. Here's the full source code.\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\tfmt.Println(\"hello world\")\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-http-request-handling":{"intro":"This challenge aims to test your ability to use the net/http package in Golang to issue HTTP requests.","steps":[{"title":"HTTP Client","body":["You are required to write a program that sends an HTTP GET request to a server and prints the HTTP response status and the first 5 lines of the response body.","• The program should use the net/http package to issue an HTTP GET request. • The program should print the HTTP response status. • The program should print the first 5 lines of the response body. • The program should handle errors gracefully."],"code":[{"lang":"sh","text":"$ go run http-clients.go\nResponse status: 200 OK\n<!DOCTYPE html>\n<html>\n  <head>\n    <meta charset=\"utf-8\">\n    <title>Go by Example</title>"}]}],"commands":["go run http-clients.go"],"reference":[{"path":"http-client.go","text":"// The Go standard library comes with excellent support\n// for HTTP clients and servers in the `net/http`\n// package. In this example we'll use it to issue simple\n// HTTP requests.\npackage main\n\nimport (\n\t\"bufio\"\n\t\"fmt\"\n\t\"net/http\"\n)\n\nfunc main() {\n\n\t// Issue an HTTP GET request to a server. `http.Get` is a\n\t// convenient shortcut around creating an `http.Client`\n\t// object and calling its `Get` method; it uses the\n\t// `http.DefaultClient` object which has useful default\n\t// settings.\n\tresp, err := http.Get(\"https://gobyexample.com\")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\t// Print the HTTP response status.\n\tfmt.Println(\"Response status:\", resp.Status)\n\n\t// Print the first 5 lines of the response body.\n\tscanner := bufio.NewScanner(resp.Body)\n\tfor i := 0; scanner.Scan() && i < 5; i++ {\n\t\tfmt.Println(scanner.Text())\n\t}\n\n\tif err := scanner.Err(); err != nil {\n\t\tpanic(err)\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-build-basic-http-server-in-go":{"intro":"This challenge aims to test your ability to write a basic HTTP server using the net/http package in Golang.","steps":[{"title":"HTTP Server","body":["You are required to write a simple HTTP server that can handle two routes: /hello and /headers. The /hello route should return a simple \"hello\" response, while the /headers route should return all the HTTP request headers.","• The server should use the net/http package. • The /hello route should return a \"hello\" response. • The /headers route should return all the HTTP request headers. • The server should listen on port 8090."],"code":[{"lang":"sh","text":"# Run the server in the background.\n$ go run http-servers.go &\n\n# Access the `/hello` route.\n$ curl localhost:8090/hello\nhello"}]}],"commands":["go run http-servers.go &","curl localhost:8090/hello"],"reference":[{"path":"http-server.go","text":"// Writing a basic HTTP server is easy using the\n// `net/http` package.\npackage main\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n)\n\n// A fundamental concept in `net/http` servers is\n// *handlers*. A handler is an object implementing the\n// `http.Handler` interface. A common way to write\n// a handler is by using the `http.HandlerFunc` adapter\n// on functions with the appropriate signature.\nfunc hello(w http.ResponseWriter, req *http.Request) {\n\n\t// Functions serving as handlers take a\n\t// `http.ResponseWriter` and a `http.Request` as\n\t// arguments. The response writer is used to fill in the\n\t// HTTP response. Here our simple response is just\n\t// \"hello\\n\".\n\tfmt.Fprintf(w, \"hello\\n\")\n}\n\nfunc headers(w http.ResponseWriter, req *http.Request) {\n\n\t// This handler does something a little more\n\t// sophisticated by reading all the HTTP request\n\t// headers and echoing them into the response body.\n\tfor name, headers := range req.Header {\n\t\tfor _, h := range headers {\n\t\t\tfmt.Fprintf(w, \"%v: %v\\n\", name, h)\n\t\t}\n\t}\n}\n\nfunc main() {\n\n\t// We register our handlers on server routes using the\n\t// `http.HandleFunc` convenience function. It sets up\n\t// the *default router* in the `net/http` package and\n\t// takes a function as an argument.\n\thttp.HandleFunc(\"/hello\", hello)\n\thttp.HandleFunc(\"/headers\", headers)\n\n\t// Finally, we call the `ListenAndServe` with the port\n\t// and a handler. `nil` tells it to use the default\n\t// router we've just set up.\n\thttp.ListenAndServe(\":8090\", nil)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-if-else-branching":{"intro":"The if-else challenge in Golang is designed to test your knowledge of branching with if and else statements in Go.","steps":[{"title":"If Else","body":["You are required to complete the checkNumber function that takes an integer as input and returns a string. If the number is even, return \"even\", otherwise return \"odd\".","• The function should be named checkNumber. • The function should take an integer as input. • The function should return a string. • If the number is even, return \"even\". • If the number is odd, return \"odd\"."],"code":[{"lang":"sh","text":"$ go run if-else.go\n7 is odd\n8 is divisible by 4\n9 has 1 digit\n\n# There is no [ternary if](https://en.wikipedia.org/wiki/%3F:)\n# in Go, so you'll need to use a full `if` statement even\n# for basic conditions."}]}],"commands":["go run if-else.go"],"reference":[{"path":"if-else.go","text":"// Branching with `if` and `else` in Go is\n// straight-forward.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Here's a basic example.\n\tif 7%2 == 0 {\n\t\tfmt.Println(\"7 is even\")\n\t} else {\n\t\tfmt.Println(\"7 is odd\")\n\t}\n\n\t// You can have an `if` statement without an else.\n\tif 8%4 == 0 {\n\t\tfmt.Println(\"8 is divisible by 4\")\n\t}\n\n\t// A statement can precede conditionals; any variables\n\t// declared in this statement are available in the current\n\t// and all subsequent branches.\n\tif num := 9; num < 0 {\n\t\tfmt.Println(num, \"is negative\")\n\t} else if num < 10 {\n\t\tfmt.Println(num, \"has 1 digit\")\n\t} else {\n\t\tfmt.Println(num, \"has multiple digits\")\n\t}\n}\n\n// Note that you don't need parentheses around conditions\n// in Go, but that the braces are required."}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-interface-exploration":{"intro":"This challenge is about interfaces in Golang. Interfaces are named collections of method signatures.","steps":[{"title":"Interfaces","body":["The problem is to implement an interface in Go, we just need to implement all the methods in the interface. Here we implement geometry on rects and circles.","• Implement an interface in Go. • Implement all the methods in the interface. • Use a generic measure function to work on any geometry. • Use instances of circle and rect structs as arguments to measure."],"code":[{"lang":"sh","text":"$ go run interfaces.go\n{3 4}\n12\n14\n{5}\n78.53981633974483\n31.41592653589793\n\n# To learn more about Go's interfaces, check out this\n# [great blog post](https://jordanorelli.tumblr.com/post/32665860244/how-to-use-interfaces-in-go)."}]}],"commands":["go run interfaces.go"],"reference":[{"path":"interfaces.go","text":"// _Interfaces_ are named collections of method\n// signatures.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math\"\n)\n\n// Here's a basic interface for geometric shapes.\ntype geometry interface {\n\tarea() float64\n\tperim() float64\n}\n\n// For our example we'll implement this interface on\n// `rect` and `circle` types.\ntype rect struct {\n\twidth, height float64\n}\ntype circle struct {\n\tradius float64\n}\n\n// To implement an interface in Go, we just need to\n// implement all the methods in the interface. Here we\n// implement `geometry` on `rect`s.\nfunc (r rect) area() float64 {\n\treturn r.width * r.height\n}\nfunc (r rect) perim() float64 {\n\treturn 2*r.width + 2*r.height\n}\n\n// The implementation for `circle`s.\nfunc (c circle) area() float64 {\n\treturn math.Pi * c.radius * c.radius\n}\nfunc (c circle) perim() float64 {\n\treturn 2 * math.Pi * c.radius\n}\n\n// If a variable has an interface type, then we can call\n// methods that are in the named interface. Here's a\n// generic `measure` function taking advantage of this\n// to work on any `geometry`.\nfunc measure(g geometry) {\n\tfmt.Println(g)\n\tfmt.Println(g.area())\n\tfmt.Println(g.perim())\n}\n\nfunc main() {\n\tr := rect{width: 3, height: 4}\n\tc := circle{radius: 5}\n\n\t// The `circle` and `rect` struct types both\n\t// implement the `geometry` interface so we can use\n\t// instances of\n\t// these structs as arguments to `measure`.\n\tmeasure(r)\n\tmeasure(c)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-concise-go-text-transformation":{"intro":"The Line Filters challenge is a common type of program that reads input on stdin, processes it, and then prints some derived result to stdout. The purpose of this challenge is to write a Go program that reads input text and modifies it according to specific requirements.","steps":[{"title":"Line Filters","body":["The problem to be solved in this challenge is to write a Go program that reads input text from stdin, capitalizes all the letters in the text, and then prints the modified text to stdout.","• The program must read input text from stdin. • The program must capitalize all the letters in the input text. • The program must print the modified text to stdout."],"code":[{"lang":"sh","text":"# To try out our line filter, first make a file with a few\n# lowercase lines.\n$ echo 'hello' > /tmp/lines\n$ echo 'filter' >> /tmp/lines\n\n# Then use the line filter to get uppercase lines.\n$ cat /tmp/lines | go run line-filters.go\nHELLO\nFILTER"}]}],"commands":["echo 'hello' > /tmp/lines","echo 'filter' >> /tmp/lines","cat /tmp/lines | go run line-filters.go"],"reference":[{"path":"line-filters.go","text":"// A _line filter_ is a common type of program that reads\n// input on stdin, processes it, and then prints some\n// derived result to stdout. `grep` and `sed` are common\n// line filters.\n\n// Here's an example line filter in Go that writes a\n// capitalized version of all input text. You can use this\n// pattern to write your own Go line filters.\npackage main\n\nimport (\n\t\"bufio\"\n\t\"fmt\"\n\t\"os\"\n\t\"strings\"\n)\n\nfunc main() {\n\n\t// Wrapping the unbuffered `os.Stdin` with a buffered\n\t// scanner gives us a convenient `Scan` method that\n\t// advances the scanner to the next token; which is\n\t// the next line in the default scanner.\n\tscanner := bufio.NewScanner(os.Stdin)\n\n\tfor scanner.Scan() {\n\t\t// `Text` returns the current token, here the next line,\n\t\t// from the input.\n\t\tucl := strings.ToUpper(scanner.Text())\n\n\t\t// Write out the uppercased line.\n\t\tfmt.Println(ucl)\n\t}\n\n\t// Check for errors during `Scan`. End of file is\n\t// expected and not reported by `Scan` as an error.\n\tif err := scanner.Err(); err != nil {\n\t\tfmt.Fprintln(os.Stderr, \"error:\", err)\n\t\tos.Exit(1)\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-creating-and-manipulating-go-maps":{"intro":"In Go, maps are built-in associative data types that allow you to store key/value pairs. This challenge will test your ability to create, manipulate, and delete key/value pairs in a map.","steps":[{"title":"Maps","body":["In this challenge, you will need to create a map that stores the number of times each word appears in a given string. You will need to split the string into words, and then iterate over each word, adding it to the map if it doesn't already exist, or incrementing its count if it does.","• You must use a map to store the word counts. • You must split the input string into words. • You must iterate over each word in the input string. • You must add each word to the map if it doesn't already exist, or increment its count if it does."],"code":[{"lang":"sh","text":"# Note that maps appear in the form `map[k:v k:v]` when\n# printed with `fmt.Println`.\n$ go run maps.go\nmap: map[k1:7 k2:13]\nv1: 7\nv3: 0\nlen: 2\nmap: map[k1:7]\nprs: false\nmap: map[bar:2 foo:1]"}]}],"commands":["go run maps.go"],"reference":[{"path":"maps.go","text":"// _Maps_ are Go's built-in [associative data type](https://en.wikipedia.org/wiki/Associative_array)\n// (sometimes called _hashes_ or _dicts_ in other languages).\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// To create an empty map, use the builtin `make`:\n\t// `make(map[key-type]val-type)`.\n\tm := make(map[string]int)\n\n\t// Set key/value pairs using typical `name[key] = val`\n\t// syntax.\n\tm[\"k1\"] = 7\n\tm[\"k2\"] = 13\n\n\t// Printing a map with e.g. `fmt.Println` will show all of\n\t// its key/value pairs.\n\tfmt.Println(\"map:\", m)\n\n\t// Get a value for a key with `name[key]`.\n\tv1 := m[\"k1\"]\n\tfmt.Println(\"v1:\", v1)\n\n\t// If the key doesn't exist, the\n\t// [zero value](https://go.dev/ref/spec#The_zero_value) of the\n\t// value type is returned.\n\tv3 := m[\"k3\"]\n\tfmt.Println(\"v3:\", v3)\n\n\t// The builtin `len` returns the number of key/value\n\t// pairs when called on a map.\n\tfmt.Println(\"len:\", len(m))\n\n\t// The builtin `delete` removes key/value pairs from\n\t// a map.\n\tdelete(m, \"k2\")\n\tfmt.Println(\"map:\", m)\n\n\t// The optional second return value when getting a\n\t// value from a map indicates if the key was present\n\t// in the map. This can be used to disambiguate\n\t// between missing keys and keys with zero values\n\t// like `0` or `\"\"`. Here we didn't need the value\n\t// itself, so we ignored it with the _blank identifier_\n\t// `_`.\n\t_, prs := m[\"k2\"]\n\tfmt.Println(\"prs:\", prs)\n\n\t// You can also declare and initialize a new map in\n\t// the same line with this syntax.\n\tn := map[string]int{\"foo\": 1, \"bar\": 2}\n\tfmt.Println(\"map:\", n)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-programming-method":{"intro":"This challenge aims to test the knowledge of the Go programming language's method feature.","steps":[{"title":"Methods","body":["The code provided defines a struct type called rect with two fields, width and height. Two methods are defined for this struct type, area and perim. The area method calculates the area of the rectangle, and the perim method calculates the perimeter of the rectangle. The main function calls these two methods and prints their results.","• The area method should have a receiver type of *rect. • The perim method should have a receiver type of rect. • The area method should return the area of the rectangle. • The perim method should return the perimeter of the rectangle. • The main function should call both methods and print their results."],"code":[{"lang":"sh","text":"$ go run methods.go\narea: 50\nperim: 30\narea: 50\nperim: 30\n\n# Next we'll look at Go's mechanism for grouping and\n# naming related sets of methods: interfaces."}]}],"commands":["go run methods.go"],"reference":[{"path":"methods.go","text":"// Go supports _methods_ defined on struct types.\n\npackage main\n\nimport \"fmt\"\n\ntype rect struct {\n\twidth, height int\n}\n\n// This `area` method has a _receiver type_ of `*rect`.\nfunc (r *rect) area() int {\n\treturn r.width * r.height\n}\n\n// Methods can be defined for either pointer or value\n// receiver types. Here's an example of a value receiver.\nfunc (r rect) perim() int {\n\treturn 2*r.width + 2*r.height\n}\n\nfunc main() {\n\tr := rect{width: 10, height: 5}\n\n\t// Here we call the 2 methods defined for our struct.\n\tfmt.Println(\"area: \", r.area())\n\tfmt.Println(\"perim:\", r.perim())\n\n\t// Go automatically handles conversion between values\n\t// and pointers for method calls. You may want to use\n\t// a pointer receiver type to avoid copying on method\n\t// calls or to allow the method to mutate the\n\t// receiving struct.\n\trp := &r\n\tfmt.Println(\"area: \", rp.area())\n\tfmt.Println(\"perim:\", rp.perim())\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-multiple-return-values":{"intro":"In Go, functions can return multiple values. This feature is commonly used to return both a result and an error value from a function.","steps":[{"title":"Multiple Return Values","body":["Complete the swap function to return two input parameters in reverse order.","• The swap function should take two integers as input parameters. • The swap function should return two integers in reverse order."],"code":[{"lang":"sh","text":"$ go run multiple-return-values.go\n3\n7\n7\n\n# Accepting a variable number of arguments is another nice\n# feature of Go functions; we'll look at this next."}]}],"commands":["go run multiple-return-values.go"],"reference":[{"path":"multiple-return-values.go","text":"// Go has built-in support for _multiple return values_.\n// This feature is used often in idiomatic Go, for example\n// to return both result and error values from a function.\n\npackage main\n\nimport \"fmt\"\n\n// The `(int, int)` in this function signature shows that\n// the function returns 2 `int`s.\nfunc vals() (int, int) {\n\treturn 3, 7\n}\n\nfunc main() {\n\n\t// Here we use the 2 different return values from the\n\t// call with _multiple assignment_.\n\ta, b := vals()\n\tfmt.Println(a)\n\tfmt.Println(b)\n\n\t// If you only want a subset of the returned values,\n\t// use the blank identifier `_`.\n\t_, c := vals()\n\tfmt.Println(c)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-concurrent-data-access-with-mutexes":{"intro":"This challenge aims to demonstrate how to use mutexes to safely access data across multiple goroutines.","steps":[{"title":"Mutexes","body":["The problem to be solved in this challenge is to increment a named counter in a loop using multiple goroutines, and ensure that the access to the counter is synchronized.","• Use a Container struct to hold a map of counters. • Use a Mutex to synchronize access to the counters map. • The Container struct should have an inc method that takes a name string and increments the corresponding counter in the counters map. • The inc method should lock the mutex before accessing the counters map, and unlock it at the end of the function using a defer statement. • Use the sync.WaitGroup struct to wait for the goroutines to finish. • Use the fmt.Println function to print the counters map."],"code":[{"lang":"sh","text":"# Running the program shows that the counters\n# updated as expected.\n\n# Next we'll look at implementing this same state\n# management task using only goroutines and channels."}]}],"commands":[],"reference":[{"path":"mutexes.go","text":"// In the previous example we saw how to manage simple\n// counter state using [atomic operations](atomic-counters).\n// For more complex state we can use a [_mutex_](https://en.wikipedia.org/wiki/Mutual_exclusion)\n// to safely access data across multiple goroutines.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"sync\"\n)\n\n// Container holds a map of counters; since we want to\n// update it concurrently from multiple goroutines, we\n// add a `Mutex` to synchronize access.\n// Note that mutexes must not be copied, so if this\n// `struct` is passed around, it should be done by\n// pointer.\ntype Container struct {\n\tmu       sync.Mutex\n\tcounters map[string]int\n}\n\nfunc (c *Container) inc(name string) {\n\t// Lock the mutex before accessing `counters`; unlock\n\t// it at the end of the function using a [defer](defer)\n\t// statement.\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tc.counters[name]++\n}\n\nfunc main() {\n\tc := Container{\n\t\t// Note that the zero value of a mutex is usable as-is, so no\n\t\t// initialization is required here.\n\t\tcounters: map[string]int{\"a\": 0, \"b\": 0},\n\t}\n\n\tvar wg sync.WaitGroup\n\n\t// This function increments a named counter\n\t// in a loop.\n\tdoIncrement := func(name string, n int) {\n\t\tfor i := 0; i < n; i++ {\n\t\t\tc.inc(name)\n\t\t}\n\t\twg.Done()\n\t}\n\n\t// Run several goroutines concurrently; note\n\t// that they all access the same `Container`,\n\t// and two of them access the same counter.\n\twg.Add(3)\n\tgo doIncrement(\"a\", 10000)\n\tgo doIncrement(\"a\", 10000)\n\tgo doIncrement(\"b\", 10000)\n\n\t// Wait for the goroutines to finish\n\twg.Wait()\n\tfmt.Println(c.counters)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-non-blocking-channel-operations":{"intro":"This challenge aims to test your understanding of non-blocking channel operations in Golang. You will be required to implement non-blocking sends, receives, and multi-way selects using the select statement with a default clause.","steps":[{"title":"Non-Blocking Channel Operations","body":["Non-Blocking Channel Operations","The problem to be solved in this challenge is to implement non-blocking channel operations using the select statement with a default clause.","• Implement a non-blocking receive on a channel using the select statement with a default clause. • Implement a non-blocking send on a channel using the select statement with a default clause. • Implement a multi-way non-blocking select using the select statement with multiple case clauses and a default clause."],"code":[{"lang":"sh","text":"$ go run non-blocking-channel-operations.go\nno message received\nno message sent\nno activity"}]}],"commands":["go run non-blocking-channel-operations.go"],"reference":[{"path":"non-blocking-channel-operations.go","text":"// Basic sends and receives on channels are blocking.\n// However, we can use `select` with a `default` clause to\n// implement _non-blocking_ sends, receives, and even\n// non-blocking multi-way `select`s.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\tmessages := make(chan string)\n\tsignals := make(chan bool)\n\n\t// Here's a non-blocking receive. If a value is\n\t// available on `messages` then `select` will take\n\t// the `<-messages` `case` with that value. If not\n\t// it will immediately take the `default` case.\n\tselect {\n\tcase msg := <-messages:\n\t\tfmt.Println(\"received message\", msg)\n\tdefault:\n\t\tfmt.Println(\"no message received\")\n\t}\n\n\t// A non-blocking send works similarly. Here `msg`\n\t// cannot be sent to the `messages` channel, because\n\t// the channel has no buffer and there is no receiver.\n\t// Therefore the `default` case is selected.\n\tmsg := \"hi\"\n\tselect {\n\tcase messages <- msg:\n\t\tfmt.Println(\"sent message\", msg)\n\tdefault:\n\t\tfmt.Println(\"no message sent\")\n\t}\n\n\t// We can use multiple `case`s above the `default`\n\t// clause to implement a multi-way non-blocking\n\t// select. Here we attempt non-blocking receives\n\t// on both `messages` and `signals`.\n\tselect {\n\tcase msg := <-messages:\n\t\tfmt.Println(\"received message\", msg)\n\tcase sig := <-signals:\n\t\tfmt.Println(\"received signal\", sig)\n\tdefault:\n\t\tfmt.Println(\"no activity\")\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-parse-numbers-in-go":{"intro":"The purpose of this challenge is to demonstrate how to parse numbers from strings in Go.","steps":[{"title":"Number Parsing","body":["Parsing numbers from strings is a common task in many programs. This challenge requires you to use the built-in strconv package to parse different types of numbers from strings.","• Use the strconv package to parse numbers from strings. • Parse a float with ParseFloat. • Parse an int with ParseInt. • Parse a hex-formatted number with ParseInt. • Parse an unsigned int with ParseUint. • Parse a base-10 int with Atoi. • Handle errors returned by the parse functions."],"code":[{"lang":"sh","text":"$ go run number-parsing.go\n1.234\n123\n456\n789\n135\nstrconv.ParseInt: parsing \"wat\": invalid syntax\n\n# Next we'll look at another common parsing task: URLs."}]}],"commands":["go run number-parsing.go"],"reference":[{"path":"number-parsing.go","text":"// Parsing numbers from strings is a basic but common task\n// in many programs; here's how to do it in Go.\n\npackage main\n\n// The built-in package `strconv` provides the number\n// parsing.\nimport (\n\t\"fmt\"\n\t\"strconv\"\n)\n\nfunc main() {\n\n\t// With `ParseFloat`, this `64` tells how many bits of\n\t// precision to parse.\n\tf, _ := strconv.ParseFloat(\"1.234\", 64)\n\tfmt.Println(f)\n\n\t// For `ParseInt`, the `0` means infer the base from\n\t// the string. `64` requires that the result fit in 64\n\t// bits.\n\ti, _ := strconv.ParseInt(\"123\", 0, 64)\n\tfmt.Println(i)\n\n\t// `ParseInt` will recognize hex-formatted numbers.\n\td, _ := strconv.ParseInt(\"0x1c8\", 0, 64)\n\tfmt.Println(d)\n\n\t// A `ParseUint` is also available.\n\tu, _ := strconv.ParseUint(\"789\", 0, 64)\n\tfmt.Println(u)\n\n\t// `Atoi` is a convenience function for basic base-10\n\t// `int` parsing.\n\tk, _ := strconv.Atoi(\"135\")\n\tfmt.Println(k)\n\n\t// Parse functions return an error on bad input.\n\t_, e := strconv.Atoi(\"wat\")\n\tfmt.Println(e)\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-handling-unexpected-errors-in-golang":{"intro":"The panic challenge is designed to test your ability to handle unexpected errors in Golang.","steps":[{"title":"Panic","body":["The challenge requires you to use the panic function to fail fast on errors that shouldn't occur during normal operation or that you aren't prepared to handle gracefully.","• Basic knowledge of Golang programming language. • Familiarity with error handling in Golang. • Understanding of the panic function in Golang."],"code":[{"lang":"sh","text":"# Running this program will cause it to panic, print\n# an error message and goroutine traces, and exit with\n# a non-zero status.\n\n# When first panic in `main` fires, the program exits\n# without reaching the rest of the code. If you'd like\n# to see the program try to create a temp file, comment\n# the first panic out.\n$ go run panic.go\npanic: a problem\n\ngoroutine 1 [running]:\nmain.main() /.../panic.go:12 +0x47\n...\nexit status 2\n\n# Note that unlike some languages which use exceptions\n# for handling of many errors, in Go it is idiomatic\n# to use error-indicating return values wherever possible."}]}],"commands":["go run panic.go"],"reference":[{"path":"panic.go","text":"// A `panic` typically means something went unexpectedly\n// wrong. Mostly we use it to fail fast on errors that\n// shouldn't occur during normal operation, or that we\n// aren't prepared to handle gracefully.\n\npackage main\n\nimport \"os\"\n\nfunc main() {\n\n\t// We'll use panic throughout this site to check for\n\t// unexpected errors. This is the only program on the\n\t// site designed to panic.\n\tpanic(\"a problem\")\n\n\t// A common use of panic is to abort if a function\n\t// returns an error value that we don't know how to\n\t// (or want to) handle. Here's an example of\n\t// `panic`king if we get an unexpected error when creating a new file.\n\t_, err := os.Create(\"/tmp/file\")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"}};
